INSERT IGNORE INTO habilidades (id, nombre, descripcion, categoria, nivel_minimo_aprobatorio, duracion_minutos, icono, color_hex, activo) VALUES
(9, 'Chino Nivel 1-2', 'Certificación de Mandarin Básico (Principiante)', 'idiomas', 70, 40, 'fa-language', '#10B981', 1),
(10, 'Chino Nivel 3', 'Certificación de Mandarin Intermedio-Bajo', 'idiomas', 70, 30, 'fa-language', '#F59E0B', 1),
(11, 'Chino Nivel 4', 'Certificación de Mandarin Intermedio', 'idiomas', 70, 30, 'fa-language', '#8B5CF6', 1);
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Cuál es tu número de teléfono? (你的电话号码是多少？)', 'opcion_multiple', '["¿Cómo te llamas?","¿Cuál es tu número de teléfono?","¿Dónde vives?","¿Qué hora es?"]', '¿Cuál es tu número de teléfono?', 'Traducción directa de la pregunta.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Qué día es hoy? (今天是星期几?)', 'opcion_multiple', '["¿Cuál es tu nombre?","¿Qué día es hoy?","¿Dónde estás?","¿Cómo estás?"]', '¿Qué día es hoy?', 'Traducción directa de la pregunta.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿A qué hora es tu clase de chino? (你几点去大学？)', 'opcion_multiple', '["¿A qué hora es tu clase de chino?","¿Dónde vives?","¿Cuántos años tienes?","¿Qué estudias?"]', '¿A qué hora es tu clase de chino?', 'Traducción directa de la pregunta.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Cuántas personas hay en tu casa? (你家有几个人？)', 'opcion_multiple', '["¿Cuántas personas hay en tu casa?","¿Dónde está tu casa?","¿Cuántos hermanos tienes?","¿Cómo se llaman tus padres?"]', '¿Cuántas personas hay en tu casa?', 'Traducción directa de la pregunta.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Cuál es el verbo correcto? ''Mañana yo ______ una habitación.'' (明天我______了一个房间。)', 'opcion_multiple', '["compro","comí","pedí","reservé"]', 'reservé', '訂 (ding4) significa ''reservar''. La oración es ''Mañana yo reservé una habitación''.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Cuál es el verbo correcto? ''Ayer yo ______ un correo electrónico.'' (昨天我______一个邮件。)', 'opcion_multiple', '["escribí","leo","escribo","escribiré"]', 'escribí', '写 (xie3) significa ''escribir''. Ayer indica pasado.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Cuál es el verbo correcto? ''Yo ______ un regalo a mi amigo.'' (我______他一个礼物。)', 'opcion_multiple', '["di","doy","dará","dio"]', 'di', '给 (gei3) significa ''dar''. En pasado: ''di''.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Cuál es el verbo correcto? ''Nosotros ______ español.'' (我们______西班牙语。)', 'opcion_multiple', '["hablamos","hablan","hablo","hablarán"]', 'hablamos', '说 (shuo1) significa ''hablar (un idioma)''. Nosotros (我们) es ''hablamos''.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Cuál es el verbo correcto? ''¿______ tú chino? (你______汉语吗？)', 'opcion_multiple', '["Hablas","Habla","Hablan","Hablamos"]', 'Hablas', '会 (hui4) significa ''saber/poder hacer algo''. ''¿Sabes chino?''', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Cuál es el verbo correcto? ''Él ______ muy bien chino.'' (他______汉语很好。)', 'opcion_multiple', '["habla","hablo","hablan","hablaremos"]', 'habla', '他 (ta1) es ''él''. ''Habla'' es la forma correcta.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Cuál es el verbo correcto? ''¿______ usted una habitación?'' (您______房间吗？)', 'opcion_multiple', '["Necesita","Necesitas","Necesitamos","Necesitan"]', 'Necesita', '需要 (xuyao4) significa ''necesitar''. Usted (您) es formal, ''necesita''.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Cuál es el verbo correcto? ''Mi madre ______ el desayuno.'' (我妈______早饭。)', 'opcion_multiple', '["prepara","preparo","preparas","preparan"]', 'prepara', '做 (zuo4) significa ''hacer/preparar''. 我妈 (wo3 ma) es ''mi madre''. ''Prepara''.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Cuál es el verbo correcto? ''______ a las ocho.'' (八点______。)', 'opcion_multiple', '["Voy","Vas","Va","Vamos"]', 'Voy', '去 (qu4) significa ''ir''. ''Voy a las ocho'' (我八点去).', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, '¿Cuál es el verbo correcto? ''¿______ tú el baño?'' (你______洗手间吗？)', 'opcion_multiple', '["Conoces","Sabes","Encuentras","Ves"]', 'Sabes', '知道 (zhi1dao4) significa ''saber/conocer información''. ¿Sabes dónde está el baño?', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Ordena las palabras: ''hermana / tienes / cuántas / tú / ?'' (你有几个妹妹？)', 'opcion_multiple', '["Tienes cuántas hermanas.","Cuántas hermanas tienes tú.","Tú cuántas hermanas tienes.","¿Tienes cuántas hermanas?"]', '¿Tienes cuántas hermanas?', 'La estructura correcta en español es: ¿Cuántas + sustantivo + tienes? En chino: 你 + 有 + 几 + 妹妹 + 吗？', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Ordena las palabras: ''yo / una / tengo / hermana.'' (我有一个妹妹。)', 'opcion_multiple', '["Tengo yo una hermana.","Una hermana tengo yo.","Yo tengo una hermana.","Hermana una tengo yo."]', 'Yo tengo una hermana.', 'Estructura: Sujeto (我) + verbo (有) + objeto (一个妹妹).', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Ordena las palabras: ''usted / qué / para / almuerza / ?'' (您午饭吃什么？)', 'opcion_multiple', '["¿Qué almuerza usted?","Usted almuerza qué.","Almuerza usted qué.","¿Usted qué almuerza?"]', '¿Qué almuerza usted?', 'La estructura correcta es: ¿Qué + verbo + sujeto?. 吃 (chi1) = comer.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Ordena las palabras: ''casa / está / la / dónde / ?'' (家在哪里？)', 'opcion_multiple', '["¿Dónde está la casa?","Casa está dónde.","Está dónde la casa.","¿La casa dónde está?"]', '¿Dónde está la casa?', '¿Dónde + está + el objeto?. 家 (jia1) = casa/familia.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Ordena las palabras: ''mi / trabajo / está / lejos / .'' (我的工作很远。)', 'opcion_multiple', '["Mi trabajo está lejos.","Está lejos mi trabajo.","Trabajo mi está lejos.","Lejos está mi trabajo."]', 'Mi trabajo está lejos.', 'Mi (我的) + sustantivo (工作) + verbo (está) + adjetivo (lejos).', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Ordena las palabras: ''me / gusta / el / café / .'' (我喜欢咖啡。)', 'opcion_multiple', '["Me gusta el café.","Gusta me el café.","Café me gusta.","El café me gusta."]', 'Me gusta el café.', 'Me gusta + sustantivo. 喜欢 (xi3huan1) = gustar.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Ordena las palabras: ''no / me / gusta / el / arroz / .'' (我不喜欢米饭。)', 'opcion_multiple', '["No me gusta el arroz.","Me no gusta el arroz.","Arroz no me gusta.","No gusta me el arroz."]', 'No me gusta el arroz.', 'No + me gusta + sustantivo. 不 (bu4) = no.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Ordena las palabras: ''nosotros / vamos / a / la / escuela / .'' (我们去学校。)', 'opcion_multiple', '["Vamos nosotros a la escuela.","Nosotros vamos a la escuela.","A la escuela vamos nosotros.","Escuela vamos nosotros a."]', 'Nosotros vamos a la escuela.', 'Nosotros (我们) + vamos (去) + destino (学校).', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Ordena las palabras: ''ella / estudia / chino / .'' (她学汉语。)', 'opcion_multiple', '["Ella estudia chino.","Estudia ella chino.","Chino estudia ella.","Ella chino estudia."]', 'Ella estudia chino.', 'Ella (她) + estudia (学) + idioma (汉语).', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Ordena las palabras: ''él / come / manzanas / .'' (他吃苹果。)', 'opcion_multiple', '["Él come manzanas.","Come él manzanas.","Manzanas come él.","Él manzanas come."]', 'Él come manzanas.', 'Él (他) + come (吃) + objeto (苹果).', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''¿Dónde está el baño?'' (洗手间在哪里？)', 'opcion_multiple', '["Where is the restaurant?","How old is she?","Where is the bathroom?","What time is it?"]', 'Where is the bathroom?', '洗手间 (xishoujian1) = baño. 在 (zai4) = está/en. 哪里 (nali3) = dónde.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''She studies Chinese.'' (她学汉语。)', 'opcion_multiple', '["She teaches Chinese.","She studies Chinese.","She speaks Chinese.","She likes Chinese."]', 'She studies Chinese.', '她 (ta1) = ella. 学 (xue2) = estudiar. 汉语 (hanyu3) = chino.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''I like apples.'' (我喜欢苹果。)', 'opcion_multiple', '["I eat apples.","I buy apples.","I like apples.","I don''t like apples."]', 'I like apples.', '我 (wo3) = yo. 喜欢 (xi3huan1) = gustar. 苹果 (ping2guo3) = manzana.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''The book is on the table.'' (书在桌子上。)', 'opcion_multiple', '["The book is under the table.","The book is on the table.","The book is next to the table.","The book is far from the table."]', 'The book is on the table.', '书 (shu1) = libro. 在 (zai4) = está/en. 桌子上 (zhuozi shang) = encima de la mesa.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''My phone number is 12345.'' (我的电话号码是12345。)', 'opcion_multiple', '["My address is 12345.","My phone number is 12345.","My age is 12345.","My room number is 12345."]', 'My phone number is 12345.', '我的 (wo3 de) = mi. 电话号码 (dian4hua4 hao4ma3) = número de teléfono. 是 (shi4) = es.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''We are friends.'' (我们是朋友。)', 'opcion_multiple', '["They are friends.","We are friends.","You are friends.","He is a friend."]', 'We are friends.', '我们 (wo3men) = nosotros. 是 (shi4) = somos/son/eres. 朋友 (peng2you3) = amigos.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''I don''t know.'' (我不知道。)', 'opcion_multiple', '["I don''t know.","I know.","I don''t want to.","I don''t like it."]', 'I don''t know.', '我 (wo3) = yo. 不 (bu4) = no. 知道 (zhi1dao4) = saber/conocer.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''Good morning!'' (早上好！)', 'opcion_multiple', '["Good afternoon!","Good morning!","Good night!","Goodbye!"]', 'Good morning!', '早上 (zao3shang) = mañana. 好 (hao3) = bueno.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''How much does it cost?'' (多少钱？)', 'opcion_multiple', '["How much does it cost?","How many people?","How old is he?","How are you?"]', 'How much does it cost?', '多少 (duo1shao3) = cuánto. 钱 (qian2) = dinero.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''Thank you very much.'' (非常感谢！)', 'opcion_multiple', '["You''re welcome.","Thank you very much.","Excuse me.","See you later."]', 'Thank you very much.', '非常 (fei1chang2) = muy. 感谢 (gan3xie4) = gracias.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''This is my family.'' (这是我的家人。)', 'opcion_multiple', '["This is my teacher.","This is my friend.","This is my family.","This is my house."]', 'This is my family.', '这 (zhe4) = este/esta. 是 (shi4) = es. 我的 (wo3 de) = mi. 家人 (jia1ren2) = familia.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''The weather is nice today.'' (今天天气很好。)', 'opcion_multiple', '["The weather was nice yesterday.","The weather will be nice tomorrow.","The weather is nice today.","The weather is cold today."]', 'The weather is nice today.', '今天 (jin1tian1) = hoy. 天气 (tian1qi4) = clima. 很好 (hen3 hao3) = muy bien/nice.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''I live in Mexico.'' (我住在墨西哥。)', 'opcion_multiple', '["I travel to Mexico.","I work in Mexico.","I live in Mexico.","I studied in Mexico."]', 'I live in Mexico.', '我 (wo3) = yo. 住 (zhu4) = vivir. 在 (zai4) = en. 墨西哥 (Mo4xi1ge2) = México.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''Do you speak Chinese?'' (你会说汉语吗？)', 'opcion_multiple', '["Can you write Chinese?","Can you read Chinese?","Do you speak Chinese?","Do you understand Chinese?"]', 'Do you speak Chinese?', '你 (ni3) = tú. 会 (hui4) = puedes/sabes. 说 (shuo1) = hablar. 汉语 (hanyu3) = chino. 吗 (ma) = partícula interrogativa.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''I have two brothers.'' (我有两个兄弟。)', 'opcion_multiple', '["I have two sisters.","I have two brothers.","I have one brother.","I have three brothers."]', 'I have two brothers.', '我 (wo3) = yo. 有 (you3) = tener. 两个 (liang3 ge) = dos. 兄弟 (xiong1di4) = hermanos (varones).', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (9, 'Traduce: ''She drinks water.'' (她喝水。)', 'opcion_multiple', '["She eats rice.","She drinks coffee.","She drinks water.","She cooks food."]', 'She drinks water.', '她 (ta1) = ella. 喝 (he1) = beber. 水 (shui3) = agua.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, '¿Cuál palabra falta? ''¿Cómo _______ ir allí?'' (怎么 _______ 去那儿？)', 'opcion_multiple', '["puedo","podemos","podrías","pueden"]', 'podemos', '在 (zai4) indica ubicación. ''¿Cómo podemos ir allí?''', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, '¿Cuál palabra falta? ''¿Qué _______ piensas de esto?'' (你觉得 _______ 怎么样？)', 'opcion_multiple', '["te","le","lo","la"]', 'te', '你觉得 (ni3 jue2de) = ¿qué opinas tú?. ''怎么样'' (zen3me yang4) = ¿cómo?.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, '¿Cuál palabra falta? ''Todas las personas _______ tienen un hobby.'' (每个人 _______ 有自己的爱好。)', 'opcion_multiple', '["también","tampoco","siempre","nunca"]', 'también', '都 (dou1) significa ''todos/también'' en este contexto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, '¿Cuál palabra falta? ''El sushi de este restaurante _______ no me gusta.'' (我觉得这个饭馆的寿司 _______ 一点也不好吃。)', 'opcion_multiple', '["realmente","mucho","poco","bastante"]', 'realmente', '一点也不 (yi1dian3 bu4) significa ''nada''. ''一点也不好吃'' = nada sabroso.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, '¿Cuál palabra falta? ''El pato asado de Beijing es _______ famoso en China.'' (北京的烤鸭在中国很 _______ )', 'opcion_multiple', '["famoso","caro","difícil","viejo"]', 'famoso', '有名 (you3ming2) = famoso.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, '¿Cuál palabra falta? ''Ir a un bar con amigos es una _______ buena idea.'' (去酒吧和朋友一起是一个 _______ idea buena.)', 'opcion_multiple', '["muy","realmente","buen","buena"]', 'buena', '好主意 (hao3 zhuyi4) = buena idea. ''una'' (un) + ''buena'' (femenino adjetivo).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, '¿Cuál palabra falta? ''Tengo examen de chino _______ .'' (我有汉语考试 _______ )', 'opcion_multiple', '["ayer","mañana","anoche","ahora"]', 'mañana', '明天 (ming2tian1) = mañana.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, '¿Cuál palabra falta? ''¿A dónde _______ de vacaciones?'' (你 _______ 去哪里 de vacaciones?)', 'opcion_multiple', '["vas","vienes","vas","voy"]', 'vas', '你 (ni3) = tú. 去 (qu4) = ir. ''¿A dónde vas de vacaciones?''', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, '¿Cuál palabra falta? ''La comida china y la occidental _______ diferentes.'' (中餐和西餐 _______ diferentes.)', 'opcion_multiple', '["son","están","fueron","van"]', 'son', '都是 (dou1 shi4) = ambas son. ''Son diferentes.''', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, '¿Cuál palabra falta? ''Muchas personas _______ en línea con amigos.'' (很多人 _______ en línea con amigos.)', 'opcion_multiple', '["leen","cantan","chatean","corren"]', 'chatean', '聊天 (liao2tian1) = chatear.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Ordena: ''es / muy / importante / para / nosotros / comer / bien.'' (对我们来说吃饭很重要。)', 'opcion_multiple', '["Para nosotros comer bien es muy importante.","Es muy importante para nosotros comer bien.","Comer bien es muy importante para nosotros.","Para nosotros es muy importante comer bien."]', 'Es muy importante para nosotros comer bien.', 'Estructura: Es + adjetivo + para + nosotros + verbo. 对我们来说 (dui4 wo3men lai2shuo1) = para nosotros.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Ordena: ''ayer / comí / demasiado / y / no / me / sentí / bien.'' (昨天我吃得太多了，所以不舒服。)', 'opcion_multiple', '["Ayer comí demasiado y no me sentí bien.","No me sentí bien porque ayer comí demasiado.","Ayer no me sentí bien por comer demasiado.","Comí demasiado ayer y me sentí mal."]', 'Ayer comí demasiado y no me sentí bien.', '吃得太多 (chi1 de tai4 duo1) = comer demasiado. 不舒服 (bu4 shu1fu2) = sentirse mal.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Ordena: ''con / amigos / a / menudo / chateo / en / línea.'' (我常常和朋友在线聊天。)', 'opcion_multiple', '["A menudo chateo con amigos en línea.","Chateo con amigos en línea a menudo.","En línea chateo con amigos a menudo.","Con amigos chateo en línea a menudo."]', 'A menudo chateo con amigos en línea.', '常常 (chang2chang2) = a menudo. 和 (he2) = con. 在线 (zai4 xian4) = en línea.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Ordena: ''ayer / no / vino / a / clase / porque / estaba / enferma.'' (昨天她没来上课，因为病了。)', 'opcion_multiple', '["Ayer no vino a clase porque estaba enferma.","No vino a clase ayer porque estaba enferma.","Porque estaba enferma, ayer no vino a clase.","Estaba enferma, así que no vino a clase ayer."]', 'Ayer no vino a clase porque estaba enferma.', '没 (méi2) = no (pasado). 来 (lái2) = venir. 因为 (yin1wei4) = porque. 病 (bìng4) = enfermedad/estar enfermo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Ordena: ''cerca / de / la / universidad / hay / un / centro / comercial / grande.'' (学校附近有一个很大的购物中心。)', 'opcion_multiple', '["Hay un centro comercial grande cerca de la universidad.","Cerca de la universidad hay un centro comercial grande.","Un centro comercial grande hay cerca de la universidad.","Cerca de la universidad un centro comercial grande hay."]', 'Cerca de la universidad hay un centro comercial grande.', '学校 (xuéxiào) = escuela/universidad. 附近 (fùjìn) = cerca/de alrededores. 一个 (yīgè) = un/una. 很大 (hěndà) = muy grande.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Ordena: ''el / mayor / deseo / de / muchas / mujeres / es / ir / de / compras.'' (很多女人最大的爱好就是购物。)', 'opcion_multiple', '["El mayor deseo de muchas mujeres es ir de compras.","Ir de compras es el mayor deseo de muchas mujeres.","Muchas mujeres desean ir de compras.","El mayor deseo de las mujeres es comprar."]', 'El mayor deseo de muchas mujeres es ir de compras.', '很多 (hěnduō) = muchas/muchos. 女人 (nǚrén) = mujeres. 最大 (zuìdà) = más grande/mayor. 爱好 (àihào) = hobby/deseo. 购物 (gòuwù) = ir de compras.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Ordena: ''ayer / olvidé / traer / el / libro / de / chino.'' (昨天我忘了带汉语书。)', 'opcion_multiple', '["Ayer olvidé traer el libro de chino.","Olvidé traer el libro de chino ayer.","Traer el libro de chino ayer olvidé.","El libro de chino ayer olvidé traer."]', 'Ayer olvidé traer el libro de chino.', '忘了 (wàng le) = olvidé. 带 (dài) = traer/llevar. 汉语书 (hànyǔ shū) = libro de chino.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Ordena: ''ella / piensa / que / este / vestido / es / especialmente / bonito.'' (她觉得这件衣服特别漂亮。)', 'opcion_multiple', '["Ella piensa que este vestido es especialmente bonito.","Este vestido es especialmente bonito, piensa ella.","Piensa ella que este vestido es especialmente bonito.","Especialmente bonito es este vestido, piensa ella."]', 'Ella piensa que este vestido es especialmente bonito.', '她觉得 (tā juédé) = ella piensa/siente. 这件 (zhè jiàn) = este/esta (ropa). 衣服 (yīfu) = ropa/vestido. 特别 (tèbié) = especialmente. 漂亮 (piàoliang) = bonito.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Ordena: ''el / oficina / abre / a / las / 9 / de / la / mañana / y / cierra / a / las / 4 / de / la / tarde.'' (办公室早上九点开门，下午四点关门。)', 'opcion_multiple', '["La oficina abre a las 9 de la mañana y cierra a las 4 de la tarde.","A las 9 de la mañana abre la oficina y a las 4 de la tarde cierra.","La oficina cierra a las 4 de la tarde y abre a las 9 de la mañana.","Abre y cierra la oficina a las 9 y 4 respectivamente."]', 'La oficina abre a las 9 de la mañana y cierra a las 4 de la tarde.', '办公室 (bàngōngshì) = oficina. 早上 (zǎoshàng) = mañana. 九点 (jiǔ diǎn) = 9 en punto. 开门 (kāimén) = abrir. 下午 (xiàwǔ) = tarde. 四点 (sì diǎn) = 4 en punto. 关门 (guānmén) = cerrar.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Ordena: ''la / cocina / está / enfrente / del / comedor.'' (厨房在餐厅的对面。)', 'opcion_multiple', '["La cocina está enfrente del comedor.","Enfrente del comedor está la cocina.","Está la cocina enfrente del comedor.","La cocina del comedor está enfrente."]', 'La cocina está enfrente del comedor.', '厨房 (chúfáng) = cocina. 在 (zài) = está/en. 餐厅 (cāntīng) = comedor/restaurante. 对面 (duìmiàn) = enfrente/opuesto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Traduce: ''I don''t like Mexican food very much because it''s too spicy.'' (我不太喜欢墨西哥菜，因为它太辣了。)', 'opcion_multiple', '["No me gusta la comida mexicana porque es muy picante.","Me gusta un poco la comida mexicana.","La comida mexicana no es picante.","Me encanta la comida mexicana."]', 'No me gusta la comida mexicana porque es muy picante.', '不太 (bù tài) = no muy/no tanto. 墨西哥菜 (Mòxīgē cài) = comida mexicana. 因为 (yīnwèi) = porque. 太 (tài) = demasiado. 辣 (là) = picante.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Traduce: ''I have a Chinese exam tomorrow, what do you think about studying together tonight?'' (我明天有中文考试，你觉得我们今晚一起学习怎么样？)', 'opcion_multiple', '["Tengo un examen de chino mañana, ¿qué te parece estudiar juntos esta noche?","Estudio chino esta noche.","Mi examen es hoy.","No quiero estudiar."]', 'Tengo un examen de chino mañana, ¿qué te parece estudiar juntos esta noche?', '明天 (míngtiān) = mañana. 有 (yǒu) = tener (evento). 中文考试 (zhōngwén kǎoshì) = examen de chino. 你觉得 (nǐ juédé) = ¿qué piensas tú?. 今晚 (jīn wǎn) = esta noche. 一起 (yīqǐ) = juntos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Traduce: ''Where are you going to travel on vacation?'' (你假期要去哪里旅游？)', 'opcion_multiple', '["¿Adónde vas a viajar en vacaciones?","¿Cuándo viajas?","¿Dónde vives?","¿Qué haces en vacaciones?"]', '¿Adónde vas a viajar en vacaciones?', '假期 (jiàqī) = vacaciones. 旅游 (lǚyóu) = viajar/turismo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Traduce: ''Chinese food and Western food are delicious, but each one is different.'' (中餐和西餐都很好吃，但是每一个都不同。)', 'opcion_multiple', '["La comida china y la occidental son sabrosas, pero cada una es diferente.","La comida china es mejor que la occidental.","Las comidas no son diferentes.","Ninguna comida es sabrosa."]', 'La comida china y la occidental son sabrosas, pero cada una es diferente.', '中餐 (zhōngcān) = comida china. 西餐 (xīcān) = comida occidental. 都 (dōu) = ambas. 很好吃 (hěn hǎochī) = muy sabrosa. 但是 (dànshì) = pero. 每一个 (měi yīgè) = cada uno. 不同 (bùtóng) = diferente.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Traduce: ''Many people like to chat online with their friends.'' (很多人喜欢和朋友在线聊天。)', 'opcion_multiple', '["Muchas personas les gusta chatear en línea con amigos.","A muchas personas les gusta chatear en línea con sus amigos.","Chatear en línea es para amigos.","No me gusta chatear."]', 'A muchas personas les gusta chatear en línea con sus amigos.', '很多 (hěnduō) = muchos/muchas. 喜欢 (xǐhuān) = gustar. 和 (hé) = con. 朋友 (péngyǒu) = amigos. 在线 (zàixiàn) = en línea. 聊天 (liáotiān) = chatear.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Traduce: ''Every day I watch the news at night.'' (我每天晚上看新闻。)', 'opcion_multiple', '["Veo las noticias todas las noches.","Veo las noticias todos los días por la noche.","Veo noticias de noche.","Veo noticias cada noche."]', 'Veo las noticias todos los días por la noche.', '每天 (měitiān) = cada día/todos los días. 晚上 (wǎnshàng) = noche. 看 (kàn) = ver. 新闻 (xīnwén) = noticias.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Traduce: ''The teacher''s house is very close to the university, 10 minutes by car.'' (老师的家离大学很近，开车十分钟。)', 'opcion_multiple', '["La casa de la maestra está muy cerca de la universidad, a 10 minutos en coche.","La casa está lejos de la universidad.","La casa está a 10 metros.","La universidad está en la casa."]', 'La casa de la maestra está muy cerca de la universidad, a 10 minutos en coche.', '老师的家 (lǎoshī de jiā) = la casa del profesor/maestra. 离 (lí) = distancia, estar lejos/cerca de. 很近 (hěn jìn) = muy cerca. 大学 (dàxué) = universidad. 开车 (kāichē) = conducir/coche. 十分钟 (shífēnzhōng) = diez minutos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Traduce: ''My teacher''s house has a very large garden.'' (我家老师有一个很大的花园。)', 'opcion_multiple', '["La casa de mi maestro tiene un jardín muy grande.","Mi casa tiene un jardín.","El jardín es pequeño.","La casa no tiene jardín."]', 'La casa de mi maestro tiene un jardín muy grande.', '我家老师 (wǒ jiā lǎoshī) = mi maestro de casa (ambiguo, quizás ''la casa de mi maestro''). 有 (yǒu) = tiene. 一个 (yīgè) = un. 很大 (hěn dà) = muy grande. 花园 (huāyuán) = jardín.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Traduce: ''The office opens at 9 am and closes at 4 pm.'' (办公室早上九点开门，下午四点关门。)', 'opcion_multiple', '["La oficina abre a las 9 am y cierra a las 4 pm.","La oficina está abierta de 9 a 4.","La oficina cierra temprano.","La oficina no abre los fines de semana."]', 'La oficina abre a las 9 am y cierra a las 4 pm.', '办公室 (bàngōngshì) = oficina. 早上 (zǎoshàng) = mañana. 九点 (jiǔ diǎn) = 9 en punto. 开门 (kāimén) = abrir. 下午 (xiàwǔ) = tarde. 四点 (sì diǎn) = 4 en punto. 关门 (guānmén) = cerrar.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (10, 'Traduce: ''I usually get up at seven in the morning.'' (我通常早上七点起床。)', 'opcion_multiple', '["Normalmente me levanto a las siete de la mañana.","Me acuesto a las siete.","Desayuno a las siete.","Trabajo a las siete."]', 'Normalmente me levanto a las siete de la mañana.', '我 (wǒ) = yo. 通常 (tōngcháng) = usualmente/normalmente. 早上 (zǎoshàng) = mañana. 七点 (qī diǎn) = 7 en punto. 起床 (qǐchuáng) = levantarse.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, '¿Cuál palabra falta? ''El tipo de cambio del dólar hoy es 20.4, _______ . (今天的美金汇率是 20.4，又_______。)', 'opcion_multiple', '["subió","bajó","se mantuvo","cambió"]', 'subió', '又 (yòu) implica ''otra vez'' o ''además''. ''Subió'' (shàng shēng) es una opción lógica.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, '¿Cuál palabra falta? ''En casi todas las casas chinas se acostumbra beber _______ . (几乎在所有的中国人家里都习惯喝 _______ 。)', 'opcion_multiple', '["té","café","leche","agua"]', 'té', '茶 (chá) = té. Es una costumbre muy arraigada en China.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, '¿Cuál palabra falta? ''Cada lugar tiene sus propias _______ . (每个地方都有他们自己的_______。)', 'opcion_multiple', '["costumbres","personas","edificios","animales"]', 'costumbres', '习惯 (xíguàn) = costumbres/hábitos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, '¿Cuál palabra falta? ''Mucha gente gusta _______ ropa vieja. (很多人喜欢_______旧了，不要的衣服。)', 'opcion_multiple', '["donar","guardar","vender","tirar"]', 'donar', '捐 (juān) = donar. ''Donar ropa vieja'' es una práctica común.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, '¿Cuál palabra falta? ''Los chinos prefieren el té con _______ fresca. (中国人喝茶喜欢用新鲜的_______ 。)', 'opcion_multiple', '["hojas","agua","leche","azúcar"]', 'hojas', '茶叶 (cháyè) = hojas de té.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, '¿Cuál palabra falta? ''_______ es la llave para abrir corazones. (_______是打开人与人之间的心灵的一把钥匙。)', 'opcion_multiple', '["La risa","La comida","La comunicación","El dinero"]', 'La comunicación', '交流 (jiāoliú) = comunicación/interacción. Es una metáfora sobre conexión humana.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, '¿Cuál palabra falta? ''El alimento principal en China es _______, en México es _______ . (中国人的主粮是_______，墨西哥人的主粮是_______。)', 'opcion_multiple', '["arroz / tortilla","noodles / frijoles","pan / arroz","arroz / maíz"]', 'arroz / tortilla', '米饭 (mǐfàn) = arroz cocido. Tortilla es un alimento básico en México.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, '¿Cuál palabra falta? ''La hora de comer en China es más _______, en Occidente es más _______ . (中国人的进食时间比较______，西方人进食时间比较_____ 。)', 'opcion_multiple', '["flexible / fija","fija / flexible","tarde / temprano","temprano / tarde"]', 'fija / flexible', '比较 (bǐjiào) = más... que. This implies a comparison of characteristics.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, '¿Cuál palabra falta? ''Perdón, no traigo _______ , solo un billete de 500 pesos. (对不起，我没带_______，只带了一张 500比索的纸币。)', 'opcion_multiple', '["monedas","tarjeta","dinero","cambio"]', 'monedas', '零钱 (língqián) = cambio/monedas sueltas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, '¿Cuál palabra falta? ''_______ es importante para el desarrollo del mundo. (_______是越来越重要对于世界的发展。)', 'opcion_multiple', '["El idioma","La tecnología","La economía","La educación"]', 'El idioma', '语言 (yǔyán) = idioma/lenguaje.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Ordena: ''desde / el / hotel / hay / una / calle / muy / ancha.'' (从酒店出来有一条很宽的大马路。)', 'opcion_multiple', '["Desde el hotel hay una calle muy ancha.","Hay una calle muy ancha desde el hotel.","Una calle muy ancha hay desde el hotel.","Desde el hotel una calle muy ancha hay."]', 'Desde el hotel hay una calle muy ancha.', '从 (cóng) = desde. 酒店 (jiǔdiàn) = hotel. 出来 (chūlái) = salir. 有 (yǒu) = hay. 一条 (yī tiáo) = una (calle). 很宽 (hěn kuān) = muy ancha. 大马路 (dà mǎlù) = calle principal.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Ordena: ''debemos / anticipar / para / volar / nosotros / comprar / el / boleto.'' (我们要提前买飞机票。)', 'opcion_multiple', '["Debemos comprar el boleto para volar con anticipación.","Para volar, debemos comprar el boleto con anticipación.","Comprar el boleto con anticipación es para volar.","Con anticipación, debemos comprar el boleto para volar."]', 'Debemos comprar el boleto para volar con anticipación.', '要 (yào) = deber/querer. 提前 (tíqián) = con anticipación. 买 (mǎi) = comprar. 飞机票 (fēijīpiào) = boleto de avión.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Ordena: ''desde / pequeño / yo / tengo / un / sueño / viajar / a / China.'' (我从小就有个去中国的旅游梦想。)', 'opcion_multiple', '["Desde pequeño yo tengo un sueño de viajar a China.","Tengo un sueño de viajar a China desde pequeño.","Un sueño de viajar a China tengo desde pequeño.","Yo desde pequeño tengo un sueño de viajar a China."]', 'Desde pequeño yo tengo un sueño de viajar a China.', '从小 (cóng xiǎo) = desde pequeño. 旅游梦想 (lǚyóu mèngxiǎng) = sueño de viaje.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Ordena: ''habitación / para / rentar / usualmente / se / paga / un / depósito / de / un / mes.'' (通常租房子要交一个月押金。)', 'opcion_multiple', '["Para rentar una habitación usualmente se paga un depósito de un mes.","Usualmente se paga un mes de depósito para rentar una habitación.","Un mes de depósito se paga usualmente para rentar una habitación.","Para rentar, usualmente pagas un mes de depósito."]', 'Para rentar una habitación usualmente se paga un depósito de un mes.', '通常 (tōngcháng) = usualmente. 租房子 (zū fángzi) = rentar una casa/habitación. 押金 (yājīn) = depósito.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Ordena: ''cinco / hoteles / estrellas / usualmente / proveen / desayuno / gratis / y / muy / bueno / servicio.'' (五星级酒店一般提供很好的免费早餐和服务。)', 'opcion_multiple', '["Los hoteles cinco estrellas usualmente proveen desayuno gratis y muy buen servicio.","Usualmente, los hoteles cinco estrellas proveen desayuno gratis y muy buen servicio.","Desayuno gratis y muy buen servicio proveen usualmente los hoteles cinco estrellas.","Proveen usualmente desayuno gratis y muy buen servicio los hoteles cinco estrellas."]', 'Los hoteles cinco estrellas usualmente proveen desayuno gratis y muy buen servicio.', '五星级 (wǔ xīng jí) = cinco estrellas. 一般 (yībān) = usualmente/generalmente. 提供 (tígōng) = proveer/ofrecer. 免费 (miǎnfèi) = gratis.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Ordena: ''puedes / pagar / con /微信 / en / un / restaurante / aquí.'' (在这里你可以用微信支付。)', 'opcion_multiple', '["Aquí puedes pagar con WeChat en un restaurante.","Puedes pagar con WeChat en un restaurante aquí.","Con WeChat puedes pagar en un restaurante aquí.","Aquí, en un restaurante, puedes pagar con WeChat."]', 'Aquí puedes pagar con WeChat en un restaurante.', '这里 (zhèlǐ) = aquí. 微信 (wēixìn) = WeChat. 支付 (zhīfù) = pagar.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Ordena: ''por / favor / dime / cuánto / dinero / queda / en / tu / tarjeta.'' (请问你卡里还剩下多少钱？)', 'opcion_multiple', '["Por favor, dime cuánto dinero queda en tu tarjeta.","Dime por favor cuánto dinero queda en tu tarjeta.","Cuánto dinero queda en tu tarjeta, por favor dime.","Por favor dime cuánto dinero queda en tu tarjeta."]', 'Por favor, dime cuánto dinero queda en tu tarjeta.', '请问 (qǐngwèn) = por favor/dime. 卡里 (kǎ lǐ) = en la tarjeta. 还剩下 (hái shèngxià) = aún queda/quedan.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Ordena: ''generalmente / para / rentar / una / casa / necesitas / pagar / un / mes / de / depósito.'' (一般来说，租房子需要付一个月的押金。)', 'opcion_multiple', '["Generalmente, para rentar una casa necesitas pagar un mes de depósito.","Para rentar una casa, generalmente necesitas pagar un mes de depósito.","Necesitas pagar un mes de depósito generalmente para rentar una casa.","Generalmente necesitas pagar un mes de depósito para rentar una casa."]', 'Generalmente, para rentar una casa necesitas pagar un mes de depósito.', '一般来说 (yī般 lái shuō) = generalmente/habitualmente. 付 (fù) = pagar.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Ordena: ''quiero / abrir / una / cuenta / bancaria / , / ¿ / qué / trámites / debo / hacer / ?'' (我想开一个银行账户，要办什么手续？)', 'opcion_multiple', '["Quiero abrir una cuenta bancaria, ¿qué trámites debo hacer?","¿Qué trámites debo hacer para abrir una cuenta bancaria?","Para abrir una cuenta bancaria, ¿qué trámites debo hacer?","Debo hacer qué trámites para abrir una cuenta bancaria."]', 'Quiero abrir una cuenta bancaria, ¿qué trámites debo hacer?', '开 (kāi) = abrir. 银行账户 (yínháng zhànghù) = cuenta bancaria. 手续 (shǒuxù) = trámites/procedimientos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Ordena: ''el / aeropuerto / está / muy / lejos / de / aquí / , / debes / ir / en / taxi.'' (机场离这里很远，你必须坐出租车去。)', 'opcion_multiple', '["El aeropuerto está muy lejos de aquí, debes ir en taxi.","Debes ir en taxi porque el aeropuerto está muy lejos de aquí.","Está muy lejos el aeropuerto de aquí, así que irás en taxi.","Irás en taxi al aeropuerto porque está muy lejos."]', 'El aeropuerto está muy lejos de aquí, debes ir en taxi.', '机场 (jīchǎng) = aeropuerto. 离 (lí) = distancia. 很远 (hěn yuǎn) = muy lejos. 必须 (bìxū) = debes/deberás. 出租车 (chūzūchē) = taxi.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Traduce: ''The exchange rate of the dollar today is 20.4, it went up again.'' (今天的美金汇率是 20.4，又涨了。)', 'opcion_multiple', '["El tipo de cambio del dólar hoy es 20.4, subió otra vez.","El tipo de cambio del dólar hoy es 20.4, bajó otra vez.","El tipo de cambio del dólar hoy es 20.4, se mantuvo.","El tipo de cambio del dólar hoy es 20.4, cambió."]', 'El tipo de cambio del dólar hoy es 20.4, subió otra vez.', '又 (yòu) = otra vez/además. 涨 (zhǎng) = subir (precios/tipo de cambio).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Traduce: ''In almost every Chinese household, they are used to drinking tea.'' (几乎在所有的中国人家里都习惯喝茶。)', 'opcion_multiple', '["En casi todas las casas chinas se acostumbra beber té.","En todas las casas chinas beben té.","En casi todas las casas chinas se come arroz.","A los chinos no les gusta el té."]', 'En casi todas las casas chinas se acostumbra beber té.', '几乎 (jīhū) = casi. 所有的 (suǒyǒu de) = todos/as. 习惯 (xíguàn) = acostumbrarse/hábito. 喝茶 (hē chá) = beber té.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Traduce: ''Each place has its own dialect and way of life.'' (每个地方都有自己的方言和生活习惯。)', 'opcion_multiple', '["Cada lugar tiene su propio dialecto y hábitos de vida.","Todos los lugares hablan igual.","Cada lugar tiene la misma cultura.","No hay diferencias entre lugares."]', 'Cada lugar tiene su propio dialecto y hábitos de vida.', '方言 (fāngyán) = dialecto. 生活习惯 (shēnghuó xíguàn) = hábitos de vida.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Traduce: ''It takes me 15 minutes to walk from the hotel to the subway station.'' (从酒店走到地铁站要15分钟。)', 'opcion_multiple', '["Tardo 15 minutos en caminar desde el hotel hasta la estación de metro.","La estación de metro está a 15 minutos.","Camino 15 minutos.","El hotel está lejos."]', 'Tardo 15 minutos en caminar desde el hotel hasta la estación de metro.', '走 (zǒu) = caminar. 地铁站 (dìtiě zhàn) = estación de metro. 要 (yào) = tomar/tardar (tiempo).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Traduce: ''Language is increasingly important for the development of the world.'' (语言对世界发展越来越重要。)', 'opcion_multiple', '["El idioma es cada vez más importante para el desarrollo del mundo.","El idioma no es importante.","El mundo no necesita idiomas.","El desarrollo no necesita idiomas."]', 'El idioma es cada vez más importante para el desarrollo del mundo.', '语言 (yǔyán) = idioma/lenguaje. 对 (duì) = para. 发展 (fāzhǎn) = desarrollo. 越来越 (yuèláiyuè) = cada vez más.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Traduce: ''The airport is very far from here, you have to go by taxi.'' (机场离这里很远，你必须坐出租车去。)', 'opcion_multiple', '["El aeropuerto está muy lejos de aquí, debes ir en taxi.","Puedes ir al aeropuerto caminando.","El aeropuerto está cerca.","Toma el autobús al aeropuerto."]', 'El aeropuerto está muy lejos de aquí, debes ir en taxi.', '机场 (jīchǎng) = aeropuerto. 离 (lí) = distancia. 很远 (hěn yuǎn) = muy lejos. 必须 (bìxū) = debes. 出租车 (chūzūchē) = taxi.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Traduce: ''Every place has its own dialect and way of life.'' (每个地方都有他们自己的方言和生活習慣。)', 'opcion_multiple', '["Cada lugar tiene su propio dialecto y forma de vivir.","Todos los lugares son iguales.","No hay diferencias culturales.","El dialecto es lo mismo en todas partes."]', 'Cada lugar tiene su propio dialecto y forma de vivir.', '每个 (měi gè) = cada. 他们自己的 (tāmen zìjǐ de) = su propio. 生活習慣 (shēnghuó xíguàn) = hábitos de vida.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Traduce: ''Generally, to rent a house you need to pay one month deposit.'' (一般来说，租房子需要付一个月的押金。)', 'opcion_multiple', '["Generalmente, para rentar una casa necesitas pagar un mes de depósito.","Rentar una casa es caro.","No necesitas pagar depósito.","Pagas el depósito al final."]', 'Generalmente, para rentar una casa necesitas pagar un mes de depósito.', '一般来说 (yībān lái shuō) = generalmente. 租 (zū) = rentar. 付 (fù) = pagar. 押金 (yājīn) = depósito.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Traduce: ''I want to open a bank account, what procedures must I do?'' (我想开一个银行账户，要办什么手续？)', 'opcion_multiple', '["Quiero abrir una cuenta bancaria, ¿qué trámites debo hacer?","Necesito dinero.","Voy al banco.","Tengo una cuenta."]', 'Quiero abrir una cuenta bancaria, ¿qué trámites debo hacer?', '开 (kāi) = abrir. 银行账户 (yínháng zhànghù) = cuenta bancaria. 手续 (shǒuxù) = trámites.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (11, 'Traduce: ''It takes 15 minutes to walk from the hotel to the subway station.'' (从酒店走到地铁站要15分钟。)', 'opcion_multiple', '["Tarda 15 minutos en caminar desde el hotel hasta la estación de metro.","Camina 15 minutos.","Hotel a metro son 15 minutos.","Metro está 15 minutos."]', 'Tarda 15 minutos en caminar desde el hotel hasta la estación de metro.', '从 (cóng) = desde. 走 (zǒu) = caminar. 要 (yào) = tomar/tardar (tiempo). 分钟 (fēnzhōng) = minutos.', 'intermedio');
